import numpy as np
import matplotlib.pyplot as plt

def f(x):
    return x**3 - 3*x**2 + 2  # f'(x) = 3x^2 - 6x = 3x(x-2)

def f_prime(x):
    return 3*x**2 - 6*x

def f_double_prime(x):
    return 6*x - 6

# 找驻点：f'(x) = 0 ⇒ x = 0 或 x = 2
critical_points = [0, 2]
print("驻点分析（二阶导数判别法）：")
for x in critical_points:
    print(f"  x = {x}: f''(x) = {f_double_prime(x):.1f}, ", end="")
    if f_double_prime(x) > 0:
        print(f"极小值，f({x}) = {f(x):.2f}")
    elif f_double_prime(x) < 0:
        print(f"极大值，f({x}) = {f(x):.2f}")
    else:
        print("二阶导数判别法失效")

# 在 [-1, 3] 上求最值
interval = [-1, 3]
candidates = critical_points + interval
values = {x: f(x) for x in candidates}
print(f"\n在 [{interval[0]}, {interval[1]}] 上：")
print(f"  最大值 = max({values}) = {max(values.values()):.2f}")
print(f"  最小值 = min({values}) = {min(values.values()):.2f}")
